import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import {
  UserProfile, ExplicitPreference, ImplicitObservation,
  BehaviorRecord, ProfileSnapshot, CourseSlot,
} from '../types';
import {
  mockUserProfile, mockExplicitPreference, mockImplicitObservations,
  mockBehaviorRecords, mockProfileSnapshot, mockCourses,
} from '../data/mockData';

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

interface ProfileStore {
  profile: UserProfile;
  explicitPreference: ExplicitPreference;
  implicitObservations: ImplicitObservation[];
  behaviorRecords: BehaviorRecord[];
  profileSnapshot: ProfileSnapshot;
  previousSnapshot: ProfileSnapshot | null;
  courses: CourseSlot[];
  showComparison: boolean;

  updateProfile: (updates: Partial<UserProfile>) => void;
  setExplicitPreference: (updates: Partial<ExplicitPreference>) => void;
  addBehaviorRecord: (record: Omit<BehaviorRecord, 'id' | 'completedAt'>) => void;
  addImplicitObservation: (obs: Omit<ImplicitObservation, 'id' | 'createdAt'>) => void;
  setObservationFeedback: (id: string, feedback: 'positive' | 'negative' | 'ignore') => void;
  addCourse: (course: Omit<CourseSlot, 'id'>) => void;
  removeCourse: (id: string) => void;
  updateSnapshot: (newSnapshot: Partial<ProfileSnapshot>) => void;
  setShowComparison: (show: boolean) => void;
  calibrateFromBehavior: (record: BehaviorRecord) => void;
}

export const useProfileStore = create<ProfileStore>()(
  persist(
    (set, get) => ({
      profile: mockUserProfile,
      explicitPreference: mockExplicitPreference,
      implicitObservations: mockImplicitObservations,
      behaviorRecords: mockBehaviorRecords,
      profileSnapshot: { ...mockProfileSnapshot },
      previousSnapshot: null,
      courses: mockCourses,
      showComparison: false,

      updateProfile: (updates) => {
        set((state) => ({ profile: { ...state.profile, ...updates } }));
      },
      setExplicitPreference: (updates) => {
        set((state) => ({ explicitPreference: { ...state.explicitPreference, ...updates } }));
      },
      addBehaviorRecord: (record) => {
        const newRecord: BehaviorRecord = {
          ...record,
          id: generateId(),
          completedAt: new Date(),
        };
        set((state) => ({
          behaviorRecords: [...state.behaviorRecords, newRecord],
          profile: {
            ...state.profile,
            completedToday: state.profile.completedToday + 1,
            tasksCompleted: state.profile.tasksCompleted + 1,
          },
        }));
        get().calibrateFromBehavior(newRecord);
      },
      addImplicitObservation: (obs) => {
        const newObs: ImplicitObservation = {
          ...obs,
          id: generateId(),
          createdAt: new Date(),
        };
        set((state) => ({
          implicitObservations: [...state.implicitObservations, newObs],
        }));
      },
      setObservationFeedback: (id, feedback) => {
        set((state) => ({
          implicitObservations: state.implicitObservations.map((obs) =>
            obs.id === id ? { ...obs, feedback, weight: feedback === 'negative' ? obs.weight * 0.5 : obs.weight } : obs
          ),
        }));
      },
      addCourse: (course) => {
        set((state) => ({
          courses: [...state.courses, { ...course, id: generateId() }],
        }));
      },
      removeCourse: (id) => {
        set((state) => ({ courses: state.courses.filter((c) => c.id !== id) }));
      },
      updateSnapshot: (newSnapshot) => {
        set((state) => ({
          previousSnapshot: { ...state.profileSnapshot },
          profileSnapshot: { ...state.profileSnapshot, ...newSnapshot },
          showComparison: true,
        }));
      },
      setShowComparison: (show) => {
        set({ showComparison: show });
      },
      calibrateFromBehavior: (record) => {
        const state = get();
        const prev = { ...state.profileSnapshot };
        const updates: Partial<ProfileSnapshot> = {};

        const isWriting = record.category === '写作' || record.category === '报告';
        const overTimeRatio = record.actualMinutes / Math.max(record.estimatedMinutes, 1);

        if (isWriting && overTimeRatio > 1.2) {
          const newFactor = Math.min(prev.writingTimeFactor + 0.1, 2.0);
          updates.writingTimeFactor = Math.round(newFactor * 10) / 10;
        }

        if (record.pauseCount >= 2 && record.estimatedMinutes > 35) {
          const newFactor = Math.min(prev.longStepPauseFactor + 0.1, 2.0);
          updates.longStepPauseFactor = Math.round(newFactor * 10) / 10;
        }

        if (record.actualMinutes > 30 && record.pauseCount >= 2) {
          updates.recommendedPomodoroMinutes = 20;
        }

        if (isWriting && overTimeRatio > 1.3) {
          updates.startWithLowPressure = true;
        }

        if (Object.keys(updates).length > 0) {
          set({
            previousSnapshot: prev,
            profileSnapshot: { ...prev, ...updates },
            showComparison: true,
          });
        }
      },
    }),
    {
      name: 'college-ddl-profile-v2',
      partialize: (state) => ({
        profile: state.profile,
        explicitPreference: state.explicitPreference,
        implicitObservations: state.implicitObservations,
        behaviorRecords: state.behaviorRecords,
        profileSnapshot: state.profileSnapshot,
        courses: state.courses,
      }),
    }
  )
);
