import { Task, RiskAssessment, CourseSlot, ProfileSnapshot } from '../types';

// Calculate available free minutes today based on current time and course schedule
export function getAvailableMinutesToday(courses: CourseSlot[]): number {
  const now = new Date();
  const todayDay = now.getDay() === 0 ? 7 : now.getDay(); // Convert Sunday=0 to 7
  const nowMinutes = now.getHours() * 60 + now.getMinutes();

  const todayCourses = courses.filter(
    (course) => course.dayOfWeek === todayDay
  );

  // Calculate minutes already occupied by courses that haven't ended yet
  let occupiedMinutes = 0;
  for (const course of todayCourses) {
    const [startH, startM] = course.startTime.split(':').map(Number);
    const [endH, endM] = course.endTime.split(':').map(Number);
    const courseStart = startH * 60 + startM;
    const courseEnd = endH * 60 + endM;

    if (courseEnd > nowMinutes) {
      // Course hasn't ended yet; count the portion after now
      const overlapStart = Math.max(courseStart, nowMinutes);
      occupiedMinutes += courseEnd - overlapStart;
    }
  }

  // Remaining minutes in the day (assume end of day = 24:00)
  const remainingInDay = 24 * 60 - nowMinutes;
  const available = remainingInDay - occupiedMinutes;

  return Math.max(0, available);
}

// Calculate total estimated minutes for a task, applying writingTimeFactor for writing tasks
function getTotalEstimatedMinutes(task: Task, profile: ProfileSnapshot): number {
  const isWritingTask = task.category === '写作' || task.category === 'writing';
  const baseTotal = task.steps.reduce(
    (sum, step) => sum + step.estimatedMinutes,
    0
  );

  if (isWritingTask && profile.writingTimeFactor > 1) {
    return Math.round(baseTotal * profile.writingTimeFactor);
  }

  return baseTotal;
}

// Assess risk for a single task
export function assessTaskRisk(
  task: Task,
  availableMinutes: number,
  profile: ProfileSnapshot
): RiskAssessment {
  const totalEstimated = getTotalEstimatedMinutes(task, profile);
  const timeGap = totalEstimated - availableMinutes;

  const now = new Date();
  const deadlineDate =
    task.deadline instanceof Date ? task.deadline : new Date(task.deadline);
  const hoursUntilDeadline =
    (deadlineDate.getTime() - now.getTime()) / (1000 * 60 * 60);

  const isWritingTask = task.category === '写作' || task.category === 'writing';

  // HIGH risk: deadline within 8 hours AND (total estimated > available minutes OR time gap > 0)
  if (hoursUntilDeadline <= 8 && (totalEstimated > availableMinutes || timeGap > 0)) {
    return {
      taskId: task.id,
      level: 'high',
      reason: `今晚截止，剩余时间不足。预估还需 ${totalEstimated} 分钟，可用仅 ${availableMinutes} 分钟，缺口 ${Math.max(0, timeGap)} 分钟。`,
      totalEstimatedMinutes: totalEstimated,
      availableMinutesToday: availableMinutes,
      timeGap,
    };
  }

  // MEDIUM risk: deadline within 24 hours, or writing category tasks that user tends to overrun
  if (
    hoursUntilDeadline <= 24 ||
    (isWritingTask && profile.writingTimeFactor > 1)
  ) {
    const reasons: string[] = [];
    if (hoursUntilDeadline <= 24) {
      reasons.push(`截止时间在 ${Math.round(hoursUntilDeadline)} 小时内`);
    }
    if (isWritingTask && profile.writingTimeFactor > 1) {
      reasons.push('写作类任务过去容易超时');
    }

    return {
      taskId: task.id,
      level: 'medium',
      reason: reasons.join('，') + '。',
      totalEstimatedMinutes: totalEstimated,
      availableMinutesToday: availableMinutes,
      timeGap,
    };
  }

  // LOW risk: deadline > 24 hours away
  return {
    taskId: task.id,
    level: 'low',
    reason: '截止时间较远，可以分散完成。',
    totalEstimatedMinutes: totalEstimated,
    availableMinutesToday: availableMinutes,
    timeGap,
  };
}

// Assess risk for all tasks
export function assessAllRisks(
  tasks: Task[],
  courses: CourseSlot[],
  profile: ProfileSnapshot
): RiskAssessment[] {
  const availableMinutes = getAvailableMinutesToday(courses);

  return tasks.map((task) => assessTaskRisk(task, availableMinutes, profile));
}
