import { BookOpen, Clock, MapPin } from 'lucide-react';
import { CourseSlot } from '../../types';

interface Props {
  courses: CourseSlot[];
}

export const CourseTimeline = ({ courses }: Props) => {
  const today = new Date().getDay() || 7;
  const todayCourses = courses
    .filter((c) => c.dayOfWeek === today)
    .sort((a, b) => a.startTime.localeCompare(b.startTime));

  const now = new Date();
  const nowMinutes = now.getHours() * 60 + now.getMinutes();

  const isCurrentCourse = (course: CourseSlot) => {
    const [sh, sm] = course.startTime.split(':').map(Number);
    const [eh, em] = course.endTime.split(':').map(Number);
    const start = sh * 60 + sm;
    const end = eh * 60 + em;
    return nowMinutes >= start && nowMinutes < end;
  };

  const isUpcoming = (course: CourseSlot) => {
    const [sh, sm] = course.startTime.split(':').map(Number);
    const start = sh * 60 + sm;
    return nowMinutes < start;
  };

  if (todayCourses.length === 0) {
    return (
      <div className="rounded-2xl bg-white/80 backdrop-blur-sm border border-gray-100 p-6">
        <div className="flex items-center gap-2 mb-4">
          <BookOpen className="w-5 h-5 text-indigo-500" />
          <h3 className="font-semibold text-gray-700">今日课程</h3>
        </div>
        <p className="text-sm text-gray-400 text-center py-4">今天没有课程，好好休息 🎉</p>
      </div>
    );
  }

  return (
    <div className="rounded-2xl bg-white/80 backdrop-blur-sm border border-gray-100 p-6">
      <div className="flex items-center gap-2 mb-4">
        <BookOpen className="w-5 h-5 text-indigo-500" />
        <h3 className="font-semibold text-gray-700">今日课程</h3>
        <span className="ml-auto text-xs text-gray-400">{todayCourses.length} 节</span>
      </div>

      <div className="relative">
        {/* 时间线竖线 */}
        <div className="absolute left-[15px] top-2 bottom-2 w-0.5 bg-gray-100" />

        <div className="space-y-3">
          {todayCourses.map((course) => {
            const current = isCurrentCourse(course);
            const upcoming = isUpcoming(course);

            return (
              <div key={course.id} className="relative flex items-start gap-3 pl-1">
                {/* 时间线圆点 */}
                <div className={`relative z-10 w-[30px] h-[30px] rounded-full flex items-center justify-center flex-shrink-0 mt-1 ${
                  current
                    ? 'bg-indigo-500 shadow-md shadow-indigo-500/30'
                    : upcoming
                      ? 'bg-white border-2 border-gray-200'
                      : 'bg-gray-100'
                }`}>
                  <div className={`w-2 h-2 rounded-full ${
                    current ? 'bg-white' : upcoming ? 'bg-gray-300' : 'bg-gray-300'
                  }`} />
                </div>

                {/* 课程卡片 */}
                <div className={`flex-1 rounded-xl p-3 transition-all ${
                  current
                    ? 'bg-indigo-50 border border-indigo-200 shadow-sm'
                    : upcoming
                      ? 'bg-gray-50 border border-gray-100'
                      : 'bg-gray-50/50 border border-gray-50 opacity-60'
                }`}>
                  <div className="flex items-center gap-2 mb-1">
                    {current && (
                      <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-indigo-500 text-white">
                        进行中
                      </span>
                    )}
                    <h4 className={`text-sm font-medium ${
                      current ? 'text-indigo-700' : 'text-gray-700'
                    }`}>
                      {course.name}
                    </h4>
                  </div>
                  <div className="flex items-center gap-3 text-xs text-gray-400">
                    <div className="flex items-center gap-1">
                      <Clock className="w-3 h-3" />
                      <span>{course.startTime} - {course.endTime}</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <MapPin className="w-3 h-3" />
                      <span>{course.location}</span>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};
