import { Step, PushPreference, ProfileSnapshot } from '../types';

// Sort steps based on push preference
export function sortSteps(
  steps: Step[],
  preference: PushPreference,
  profile: ProfileSnapshot
): Step[] {
  const sorted = [...steps];

  switch (preference) {
    case 'system': {
      if (profile.startWithLowPressure) {
        // Low-pressure first: non-key, short steps before key steps
        sorted.sort((a, b) => {
          const aLowPressure = !a.isKey && a.estimatedMinutes <= 30 ? 0 : 1;
          const bLowPressure = !b.isKey && b.estimatedMinutes <= 30 ? 0 : 1;
          if (aLowPressure !== bLowPressure) return aLowPressure - bLowPressure;
          return a.estimatedMinutes - b.estimatedMinutes;
        });
      } else {
        // Key steps first, then by estimatedMinutes ascending
        sorted.sort((a, b) => {
          if (a.isKey !== b.isKey) return a.isKey ? -1 : 1;
          return a.estimatedMinutes - b.estimatedMinutes;
        });
      }
      return sorted;
    }

    case 'easiest': {
      // By difficulty proxy: use estimatedMinutes as proxy (shorter = easier)
      sorted.sort((a, b) => a.estimatedMinutes - b.estimatedMinutes);
      return sorted;
    }

    case 'shortest': {
      // By estimatedMinutes ascending
      sorted.sort((a, b) => a.estimatedMinutes - b.estimatedMinutes);
      return sorted;
    }

    case 'most_important': {
      // isKey=true first, then by estimatedMinutes ascending
      sorted.sort((a, b) => {
        if (a.isKey !== b.isKey) return a.isKey ? -1 : 1;
        return a.estimatedMinutes - b.estimatedMinutes;
      });
      return sorted;
    }

    case 'manual': {
      // Return as-is
      return sorted;
    }
  }
}

// Get risk warning if user preference differs from system recommendation
export function getPreferenceWarning(
  steps: Step[],
  preference: PushPreference,
  profile: ProfileSnapshot
): string | null {
  const hasKeySteps = steps.some((step) => step.isKey);
  const hasLongKeySteps = steps.some(
    (step) => step.isKey && step.estimatedMinutes > 30
  );

  // Get system-sorted key step positions
  const systemSorted = sortSteps(steps, 'system', profile);
  const firstKeyIndexSystem = systemSorted.findIndex((step) => step.isKey);

  if (preference === 'easiest' && hasKeySteps) {
    // Check if system would put key steps first
    const systemWouldPutKeyFirst =
      !profile.startWithLowPressure && firstKeyIndexSystem === 0;

    if (systemWouldPutKeyFirst) {
      return '已按你的偏好调整为先做简单步骤。系统提醒：关键步骤延后可能压缩检查时间。';
    }
  }

  if (preference === 'shortest' && hasLongKeySteps) {
    // Check if system would put key steps earlier
    const userSorted = sortSteps(steps, 'shortest', profile);
    const firstKeyIndexUser = userSorted.findIndex((step) => step.isKey);

    // If key steps are pushed back compared to system order
    if (firstKeyIndexUser > firstKeyIndexSystem || firstKeyIndexSystem === 0) {
      return '已按你的偏好调整为先做短步骤。系统提醒：如果核心步骤晚于合理时间开始，可能影响最终质量。';
    }
  }

  return null;
}
