import { useState, useCallback } from 'react';
import { Settings2, GripVertical, AlertCircle, Sparkles, ChevronUp, ChevronDown } from 'lucide-react';
import { Step, PushPreference, ProfileSnapshot } from '../../types';
import { sortSteps, getPreferenceWarning } from '../../utils/stepSorter';

interface Props {
  steps: Step[];
  preference: PushPreference;
  profile: ProfileSnapshot;
  onPreferenceChange: (pref: PushPreference) => void;
  onReorder: (steps: Step[]) => void;
}

const PREFERENCE_OPTIONS: { value: PushPreference; label: string }[] = [
  { value: 'system', label: '按系统推荐' },
  { value: 'easiest', label: '先做最简单的' },
  { value: 'shortest', label: '先做最短的' },
  { value: 'most_important', label: '先做最重要的' },
  { value: 'manual', label: '手动排序' },
];

export const PushPreferencePanel = ({
  steps,
  preference,
  profile,
  onPreferenceChange,
  onReorder,
}: Props) => {
  const [manualSteps, setManualSteps] = useState<Step[]>([...steps]);

  const warning = getPreferenceWarning(steps, preference, profile);

  const displaySteps =
    preference === 'manual' ? manualSteps : sortSteps(steps, preference, profile);

  const handlePreferenceChange = useCallback(
    (newPref: PushPreference) => {
      if (newPref === 'manual') {
        setManualSteps(sortSteps(steps, 'system', profile));
      }
      onPreferenceChange(newPref);
    },
    [steps, profile, onPreferenceChange]
  );

  const moveStep = useCallback(
    (index: number, direction: 'up' | 'down') => {
      const newSteps = [...manualSteps];
      const targetIndex = direction === 'up' ? index - 1 : index + 1;
      if (targetIndex < 0 || targetIndex >= newSteps.length) return;
      [newSteps[index], newSteps[targetIndex]] = [newSteps[targetIndex], newSteps[index]];
      setManualSteps(newSteps);
      onReorder(newSteps);
    },
    [manualSteps, onReorder]
  );

  return (
    <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-6">
      <div className="flex items-center gap-2 mb-5">
        <Settings2 className="w-5 h-5 text-indigo-500" />
        <h3 className="font-semibold text-gray-800">推送偏好</h3>
      </div>

      {/* Radio-style preference buttons */}
      <div className="flex flex-wrap gap-2 mb-4">
        {PREFERENCE_OPTIONS.map((opt) => (
          <button
            key={opt.value}
            onClick={() => handlePreferenceChange(opt.value)}
            className={`px-4 py-2 rounded-xl text-sm font-medium transition-all ${
              preference === opt.value
                ? 'bg-gradient-to-r from-indigo-500 to-purple-600 text-white shadow-md shadow-indigo-500/25'
                : 'bg-gray-100 text-gray-600 hover:bg-indigo-50 hover:text-indigo-600'
            }`}
          >
            {opt.value === 'system' && <Sparkles className="w-3.5 h-3.5 inline mr-1.5" />}
            {opt.label}
          </button>
        ))}
      </div>

      {/* Warning when preference differs from system */}
      {warning && (
        <div className="flex items-start gap-2 p-3 rounded-xl bg-amber-50 border border-amber-200 mb-4">
          <AlertCircle className="w-4 h-4 text-amber-500 mt-0.5 flex-shrink-0" />
          <p className="text-sm text-amber-700">{warning}</p>
        </div>
      )}

      {/* Reordered steps preview */}
      <div className="mt-2">
        <p className="text-xs text-gray-400 mb-3">
          {preference === 'manual' ? '点击箭头调整步骤顺序' : '按当前偏好排序后的步骤预览'}
        </p>
        <div className="space-y-2">
          {displaySteps.map((step, index) => (
            <div
              key={step.id}
              className="flex items-center gap-3 p-3 rounded-xl bg-gray-50 hover:bg-indigo-50/50 transition-all group"
            >
              {preference === 'manual' && (
                <div className="flex flex-col gap-0.5">
                  <button
                    onClick={() => moveStep(index, 'up')}
                    disabled={index === 0}
                    className="p-0.5 rounded text-gray-400 hover:text-indigo-600 hover:bg-indigo-100 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
                  >
                    <ChevronUp className="w-3.5 h-3.5" />
                  </button>
                  <button
                    onClick={() => moveStep(index, 'down')}
                    disabled={index === displaySteps.length - 1}
                    className="p-0.5 rounded text-gray-400 hover:text-indigo-600 hover:bg-indigo-100 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
                  >
                    <ChevronDown className="w-3.5 h-3.5" />
                  </button>
                </div>
              )}

              {preference === 'manual' && (
                <GripVertical className="w-4 h-4 text-gray-300" />
              )}

              <span className="text-xs font-mono text-gray-300 w-5 text-center">
                {index + 1}
              </span>

              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium text-gray-700 truncate">
                    {step.title}
                  </span>
                  {step.isKey && (
                    <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-indigo-100 text-indigo-600">
                      关键
                    </span>
                  )}
                </div>
              </div>

              <span className="text-xs text-gray-400 flex-shrink-0">
                {step.estimatedMinutes} 分钟
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};
