import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { Task, Step } from '../types';
import { mockTasks } from '../data/mockData';

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

interface TasksStore {
  tasks: Task[];
  addTask: (task: Omit<Task, 'id' | 'progress' | 'status' | 'createdAt' | 'steps'>) => void;
  updateTask: (id: string, updates: Partial<Task>) => void;
  deleteTask: (id: string) => void;
  completeStep: (taskId: string, stepId: string) => void;
  toggleStep: (taskId: string, stepId: string) => void;
  setTaskSteps: (taskId: string, steps: Step[]) => void;
  reorderSteps: (taskId: string, steps: Step[]) => void;
  updateStepActual: (taskId: string, stepId: string, actualMinutes: number) => void;
  getTaskById: (id: string) => Task | undefined;
}

export const useTasksStore = create<TasksStore>()(
  persist(
    (set, get) => ({
      tasks: mockTasks,
      addTask: (taskData) => {
        const newTask: Task = {
          ...taskData,
          id: generateId(),
          progress: 0,
          status: 'pending',
          createdAt: new Date(),
          steps: [],
        };
        set((state) => ({ tasks: [...state.tasks, newTask] }));
      },
      updateTask: (id, updates) => {
        set((state) => ({
          tasks: state.tasks.map((task) =>
            task.id === id ? { ...task, ...updates } : task
          ),
        }));
      },
      deleteTask: (id) => {
        set((state) => ({ tasks: state.tasks.filter((task) => task.id !== id) }));
      },
      completeStep: (taskId, stepId) => {
        set((state) => {
          const task = state.tasks.find((t) => t.id === taskId);
          if (!task) return state;
          const updatedSteps = task.steps.map((step) =>
            step.id === stepId ? { ...step, status: 'completed' as const } : step
          );
          const completedCount = updatedSteps.filter((s) => s.status === 'completed').length;
          const progress = updatedSteps.length > 0 ? Math.round((completedCount / updatedSteps.length) * 100) : 0;
          const status = progress === 100 ? 'completed' : progress > 0 ? 'in_progress' : 'pending';
          return {
            tasks: state.tasks.map((t) =>
              t.id === taskId ? { ...t, steps: updatedSteps, progress, status } : t
            ),
          };
        });
      },
      toggleStep: (taskId, stepId) => {
        set((state) => {
          const task = state.tasks.find((t) => t.id === taskId);
          if (!task) return state;
          const updatedSteps = task.steps.map((step) =>
            step.id === stepId
              ? { ...step, status: step.status === 'completed' ? 'pending' as const : 'completed' as const }
              : step
          );
          const completedCount = updatedSteps.filter((s) => s.status === 'completed').length;
          const progress = updatedSteps.length > 0 ? Math.round((completedCount / updatedSteps.length) * 100) : 0;
          const status = progress === 100 ? 'completed' : progress > 0 ? 'in_progress' : 'pending';
          return {
            tasks: state.tasks.map((t) =>
              t.id === taskId ? { ...t, steps: updatedSteps, progress, status } : t
            ),
          };
        });
      },
      setTaskSteps: (taskId, steps) => {
        set((state) => ({
          tasks: state.tasks.map((task) =>
            task.id === taskId ? { ...task, steps } : task
          ),
        }));
      },
      reorderSteps: (taskId, steps) => {
        const reordered = steps.map((s, i) => ({ ...s, order: i + 1 }));
        set((state) => ({
          tasks: state.tasks.map((task) =>
            task.id === taskId ? { ...task, steps: reordered } : task
          ),
        }));
      },
      updateStepActual: (taskId, stepId, actualMinutes) => {
        set((state) => ({
          tasks: state.tasks.map((task) =>
            task.id === taskId
              ? { ...task, steps: task.steps.map((s) => s.id === stepId ? { ...s, actualMinutes } : s) }
              : task
          ),
        }));
      },
      getTaskById: (id) => get().tasks.find((task) => task.id === id),
    }),
    { name: 'college-ddl-tasks-v2', partialize: (state) => ({ tasks: state.tasks }) }
  )
);
