import { Task, CourseSlot, NowSuggestion, ExplicitPreference, ProfileSnapshot, RiskAssessment } from '../types';
import { getAvailableMinutesToday, assessTaskRisk } from './riskEngine';

// Get minutes until next course
export function getMinutesUntilNextCourse(courses: CourseSlot[]): number | null {
  const now = new Date();
  const todayDay = now.getDay() === 0 ? 7 : now.getDay();
  const nowMinutes = now.getHours() * 60 + now.getMinutes();

  const todayCourses = courses.filter(
    (course) => course.dayOfWeek === todayDay
  );

  let minUntilNext: number | null = null;

  for (const course of todayCourses) {
    const [startH, startM] = course.startTime.split(':').map(Number);
    const courseStart = startH * 60 + startM;

    if (courseStart > nowMinutes) {
      const diff = courseStart - nowMinutes;
      if (minUntilNext === null || diff < minUntilNext) {
        minUntilNext = diff;
      }
    }
  }

  return minUntilNext;
}

// Compare risk levels for sorting (higher risk first)
function riskLevelValue(level: RiskAssessment['level']): number {
  switch (level) {
    case 'high':
      return 3;
    case 'medium':
      return 2;
    case 'low':
      return 1;
  }
}

// Generate a suggestion for what to do now
export function generateNowSuggestion(
  tasks: Task[],
  courses: CourseSlot[],
  preference: ExplicitPreference,
  profile: ProfileSnapshot
): NowSuggestion | null {
  // 1. Filter tasks that are not completed
  const pendingTasks = tasks.filter(
    (task) => task.status !== 'completed'
  );

  if (pendingTasks.length === 0) {
    return null;
  }

  // 2. Find the highest risk task
  const availableMinutes = getAvailableMinutesToday(courses);
  const riskAssessments = pendingTasks.map((task) =>
    assessTaskRisk(task, availableMinutes, profile)
  );

  // Sort by risk level descending, then by deadline ascending (soonest first)
  const sortedIndices = riskAssessments
    .map((ra, idx) => ({ ra, idx }))
    .sort((a, b) => {
      const levelDiff = riskLevelValue(b.ra.level) - riskLevelValue(a.ra.level);
      if (levelDiff !== 0) return levelDiff;
      // Tie-break: earlier deadline first
      const deadlineA = new Date(pendingTasks[a.idx].deadline).getTime();
      const deadlineB = new Date(pendingTasks[b.idx].deadline).getTime();
      return deadlineA - deadlineB;
    });

  const riskiestIdx = sortedIndices[0].idx;
  const riskiestTask = pendingTasks[riskiestIdx];

  // 3. Get minutes until next course
  const minutesUntilNextCourse = getMinutesUntilNextCourse(courses);

  // 4. Find the first pending step of the riskiest task that fits in the available time window
  const pendingSteps = riskiestTask.steps.filter(
    (step) => step.status === 'pending'
  );

  if (pendingSteps.length === 0) {
    return null;
  }

  const timeWindow = minutesUntilNextCourse ?? availableMinutes;

  // Sort steps based on user preference for "start with low pressure"
  let candidateSteps = [...pendingSteps];
  if (profile.startWithLowPressure) {
    // Find the easiest/shortest step first
    candidateSteps.sort((a, b) => a.estimatedMinutes - b.estimatedMinutes);
  } else {
    // Default: follow the original order
    candidateSteps.sort((a, b) => a.order - b.order);
  }

  // Find the first step that fits in the time window
  let chosenStep = candidateSteps.find(
    (step) => step.estimatedMinutes <= timeWindow
  );

  // If no step fits in the window, pick the shortest one anyway
  if (!chosenStep) {
    candidateSteps.sort((a, b) => a.estimatedMinutes - b.estimatedMinutes);
    chosenStep = candidateSteps[0];
  }

  // 5. Generate suggestion text
  let text: string;
  if (minutesUntilNextCourse !== null) {
    text = `现在到下一节课还有 ${minutesUntilNextCourse} 分钟，建议先完成：${chosenStep.title}，预计 ${chosenStep.estimatedMinutes} 分钟。`;
  } else {
    text = `当前没有课程安排，建议推进：${chosenStep.title}，预计 ${chosenStep.estimatedMinutes} 分钟。`;
  }

  // 6. Build reason
  const riskLevel = riskAssessments[riskiestIdx].level;
  const reasonParts: string[] = [];
  reasonParts.push(`该任务（${riskiestTask.title}）风险等级为 ${riskLevel}`);

  if (profile.startWithLowPressure) {
    reasonParts.push('根据你的偏好，选择了耗时最短的步骤开始');
  } else {
    reasonParts.push('选择了任务中第一个待完成步骤');
  }

  if (minutesUntilNextCourse !== null) {
    reasonParts.push(`距下一节课 ${minutesUntilNextCourse} 分钟`);
  } else {
    reasonParts.push('当前无课程安排，有较充裕时间');
  }

  return {
    taskId: riskiestTask.id,
    stepId: chosenStep.id,
    text,
    reason: reasonParts.join('；') + '。',
    estimatedMinutes: chosenStep.estimatedMinutes,
  };
}
