import { useState, useEffect, useCallback } from 'react';
import { Clock, CheckCircle2, Circle, Play, Trash2, Sparkles, ChevronDown, ChevronUp, BarChart3 } from 'lucide-react';
import { Task, BehaviorRecord } from '../../types';
import { useTasksStore } from '../../stores/appStore';
import { useProfileStore } from '../../stores/profileStore';
import { PomodoroTimer } from '../Pomodoro/PomodoroTimer';
import { TimeGapAnalysis } from './TimeGapAnalysis';
import { PushPreferencePanel } from './PushPreferencePanel';
import { BehaviorRecordCard } from './BehaviorRecordCard';
import { ProfileComparisonCard } from './ProfileComparisonCard';
import { simulateAISplit } from '../../utils/aiSplit';
import { sortSteps, getPreferenceWarning } from '../../utils/stepSorter';
import { assessTaskRisk, getAvailableMinutesToday } from '../../utils/riskEngine';

interface TaskDetailProps {
  task: Task;
  onBack?: () => void;
}

export const TaskDetail = ({ task }: TaskDetailProps) => {
  const completeStep = useTasksStore((s) => s.completeStep);
const toggleStep = useTasksStore((s) => s.toggleStep);
  const setTaskSteps = useTasksStore((s) => s.setTaskSteps);
  const reorderSteps = useTasksStore((s) => s.reorderSteps);
  const deleteTask = useTasksStore((s) => s.deleteTask);
  const updateStepActual = useTasksStore((s) => s.updateStepActual);

  const profile = useProfileStore((s) => s.profile);
  const profileSnapshot = useProfileStore((s) => s.profileSnapshot);
  const previousSnapshot = useProfileStore((s) => s.previousSnapshot);
  const showComparison = useProfileStore((s) => s.showComparison);
  const setShowComparison = useProfileStore((s) => s.setShowComparison);
  const explicitPreference = useProfileStore((s) => s.explicitPreference);
  const setExplicitPreference = useProfileStore((s) => s.setExplicitPreference);
  const addBehaviorRecord = useProfileStore((s) => s.addBehaviorRecord);
  const courses = useProfileStore((s) => s.courses);

  const tasks = useTasksStore((s) => s.tasks);
  const currentTask = tasks.find((t) => t.id === task.id) || task;

  const [activeStepId, setActiveStepId] = useState<string | null>(null);
  const [isSplitting, setIsSplitting] = useState(false);
  const [lastRecord, setLastRecord] = useState<BehaviorRecord | null>(null);
  const [showBehavior, setShowBehavior] = useState(false);
  const [showPreference, setShowPreference] = useState(false);
  const [warning, setWarning] = useState<string | null>(null);

  const availableMinutes = getAvailableMinutesToday(courses);
  const risk = assessTaskRisk(currentTask, availableMinutes, profileSnapshot);
  const totalEstimated = currentTask.steps.reduce((s, st) => s + st.estimatedMinutes, 0);
  const timeGap = totalEstimated - availableMinutes;

  const displaySteps = sortSteps(currentTask.steps, explicitPreference.pushPreference, profileSnapshot);

  useEffect(() => {
    const w = getPreferenceWarning(currentTask.steps, explicitPreference.pushPreference, profileSnapshot);
    setWarning(w);
  }, [explicitPreference.pushPreference, currentTask.steps, profileSnapshot]);

  const handleAISplit = async () => {
    setIsSplitting(true);
    const steps = await simulateAISplit(
      currentTask.id, currentTask.title, currentTask.description,
      currentTask.difficulty, currentTask.category, profileSnapshot,
    );
    setTaskSteps(currentTask.id, steps);
    setIsSplitting(false);
  };

  const handleStartPomodoro = (stepId: string) => {
    setActiveStepId(stepId);
  };

  const handlePomodoroComplete = useCallback((actualMinutes: number, pauseCount: number) => {
    if (!activeStepId) return;
    const step = currentTask.steps.find((s) => s.id === activeStepId);
    if (!step) return;

    updateStepActual(currentTask.id, activeStepId, actualMinutes);
    completeStep(currentTask.id, activeStepId);

    const hour = new Date().getHours();
    const timeOfDay = hour < 12 ? 'morning' : hour < 18 ? 'afternoon' : 'evening';

    const record: BehaviorRecord = {
      id: `br-${Date.now()}`,
      stepId: activeStepId,
      taskId: currentTask.id,
      stepTitle: step.title,
      taskTitle: currentTask.title,
      category: currentTask.category,
      estimatedMinutes: step.estimatedMinutes,
      actualMinutes,
      pauseCount,
      completedAt: new Date(),
      timeOfDay,
    };

    addBehaviorRecord({
      stepId: activeStepId,
      taskId: currentTask.id,
      stepTitle: step.title,
      taskTitle: currentTask.title,
      category: currentTask.category,
      estimatedMinutes: step.estimatedMinutes,
      actualMinutes,
      pauseCount,
      timeOfDay,
    });

    setLastRecord(record);
    setShowBehavior(true);
    setActiveStepId(null);
  }, [activeStepId, currentTask, completeStep, updateStepActual, addBehaviorRecord]);

  const handleReorder = (steps: Task['steps']) => {
    reorderSteps(currentTask.id, steps);
  };

  const handlePreferenceChange = (pref: 'system' | 'easiest' | 'shortest' | 'most_important' | 'manual') => {
    setExplicitPreference({ pushPreference: pref });
  };

  const completedSteps = currentTask.steps.filter((s) => s.status === 'completed').length;
  const totalSteps = currentTask.steps.length;
  const activeStep = activeStepId ? currentTask.steps.find((s) => s.id === activeStepId) : null;

  return (
    <div className="flex flex-col h-full overflow-y-auto pr-1">
      {/* Task Header */}
      <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-5 mb-4">
        <div className="flex items-start justify-between mb-3">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-2">
              <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${
                currentTask.difficulty === 'easy' ? 'bg-green-100 text-green-700' :
                currentTask.difficulty === 'medium' ? 'bg-amber-100 text-amber-700' :
                'bg-red-100 text-red-700'
              }`}>
                {currentTask.difficulty === 'easy' ? '简单' : currentTask.difficulty === 'medium' ? '中等' : '困难'}
              </span>
              <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-indigo-100 text-indigo-700">
                {currentTask.category}
              </span>
              {risk.level === 'high' && (
                <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-700">
                  高风险
                </span>
              )}
            </div>
            <h2 className="text-lg font-bold text-gray-800 mb-1">{currentTask.title}</h2>
            <p className="text-gray-500 text-sm">{currentTask.description}</p>
          </div>
          <button
            onClick={() => deleteTask(currentTask.id)}
            className="p-2 rounded-lg text-gray-400 hover:text-red-500 hover:bg-red-50 transition-all ml-2"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>

        <div className="flex items-center gap-4 text-sm text-gray-500 mb-4">
          <div className="flex items-center gap-1.5">
            <Clock className="w-4 h-4" />
            <span>截止: {new Date(currentTask.deadline).toLocaleString('zh-CN')}</span>
          </div>
        </div>

        {totalSteps > 0 && (
          <div>
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-700">任务进度</span>
              <span className="text-sm text-gray-500">{completedSteps}/{totalSteps} 步骤</span>
            </div>
            <div className="relative h-3 bg-gray-100 rounded-full overflow-hidden">
              <div
                className="absolute left-0 top-0 h-full bg-gradient-to-r from-indigo-500 to-purple-600 rounded-full transition-all duration-500"
                style={{ width: `${currentTask.progress}%` }}
              />
            </div>
          </div>
        )}
      </div>

      {/* AI Split Button (when no steps) */}
      {totalSteps === 0 && (
        <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-6 mb-4 text-center">
          <Sparkles className="w-12 h-12 mx-auto text-indigo-300 mb-3" />
          <p className="text-gray-500 mb-4">还没有拆分步骤</p>
          <button
            onClick={handleAISplit}
            disabled={isSplitting}
            className="inline-flex items-center gap-2 px-6 py-3 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600 text-white font-medium hover:shadow-lg hover:shadow-indigo-500/25 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            {isSplitting ? (
              <span className="flex items-center gap-2">
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                AI 分析拆分中...
              </span>
            ) : (
              <>
                <Sparkles className="w-4 h-4" />
                AI 智能拆分
              </>
            )}
          </button>
        </div>
      )}

      {/* Time Gap Analysis */}
      {totalSteps > 0 && (
        <TimeGapAnalysis
          totalEstimatedMinutes={totalEstimated}
          availableMinutesToday={availableMinutes}
          timeGap={timeGap}
          taskCategory={currentTask.category}
        />
      )}

      {/* Push Preference */}
      {totalSteps > 0 && (
        <div className="mb-4">
          <button
            onClick={() => setShowPreference(!showPreference)}
            className="flex items-center gap-2 text-sm font-medium text-indigo-600 hover:text-indigo-800 mb-2"
          >
            <BarChart3 className="w-4 h-4" />
            我的推进偏好
            {showPreference ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </button>
          {showPreference && (
            <PushPreferencePanel
              steps={currentTask.steps}
              preference={explicitPreference.pushPreference}
              profile={profileSnapshot}
              onPreferenceChange={handlePreferenceChange}
              onReorder={handleReorder}
            />
          )}
          {warning && (
            <div className="mt-2 p-3 bg-amber-50 border border-amber-200 rounded-xl text-sm text-amber-700">
              {warning}
            </div>
          )}
        </div>
      )}

      {/* Steps List */}
      {totalSteps > 0 && (
        <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-5 mb-4">
          <h3 className="font-semibold text-gray-700 mb-4">执行步骤</h3>
          <div className="space-y-2.5">
            {displaySteps.map((step) => {
              const isCurrent = activeStepId === step.id;
              return (
                <div
                  key={step.id}
                  className={`p-3.5 rounded-xl border transition-all ${
                    isCurrent
                      ? 'border-indigo-500 bg-indigo-50 shadow-md'
                      : step.status === 'completed'
                        ? 'border-green-200 bg-green-50/50'
                        : 'border-gray-100 hover:border-indigo-200 hover:bg-indigo-50/30'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <button
                      onClick={() => toggleStep(currentTask.id, step.id)}
                      className={`p-1.5 rounded-full transition-all flex-shrink-0 ${
                        step.status === 'completed'
                          ? 'bg-green-500 text-white hover:bg-green-600'
                          : 'bg-gray-100 text-gray-400 hover:bg-indigo-100 hover:text-indigo-600'
                      }`}
                    >
                      {step.status === 'completed' ? (
                        <CheckCircle2 className="w-4 h-4" />
                      ) : (
                        <Circle className="w-4 h-4" />
                      )}
                    </button>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <h4 className={`font-medium text-sm ${
                          step.status === 'completed' ? 'text-gray-400 line-through' : 'text-gray-800'
                        }`}>
                          {step.title}
                        </h4>
                        {step.isKey && (
                          <span className="text-xs px-1.5 py-0.5 rounded bg-purple-100 text-purple-600">关键</span>
                        )}
                      </div>
                      <div className="flex items-center gap-3 text-xs text-gray-400 mt-1">
                        <span>预计 {step.estimatedMinutes} 分钟</span>
                        {step.actualMinutes > 0 && (
                          <span className="text-amber-500">实际 {step.actualMinutes} 分钟</span>
                        )}
                      </div>
                    </div>

                    {step.status !== 'completed' && !isCurrent && !activeStepId && (
                      <button
                        onClick={() => handleStartPomodoro(step.id)}
                        className="p-2 rounded-full bg-gradient-to-r from-indigo-500 to-purple-600 text-white hover:shadow-lg hover:shadow-indigo-500/25 transition-all flex-shrink-0"
                        title="开始番茄钟"
                      >
                        <Play className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Active Pomodoro */}
      {activeStep && (
        <PomodoroTimer
          focusDuration={explicitPreference.pomodoroDuration}
          stepTitle={activeStep.title}
          onComplete={handlePomodoroComplete}
        />
      )}

      {/* Behavior Record */}
      {showBehavior && lastRecord && (
        <BehaviorRecordCard
          record={lastRecord}
          profile={profileSnapshot}
        />
      )}

      {/* Profile Comparison */}
      {showComparison && previousSnapshot && (
        <ProfileComparisonCard
          before={previousSnapshot}
          after={profileSnapshot}
          onClose={() => setShowComparison(false)}
        />
      )}
    </div>
  );
};
