import { useState, useEffect, useRef, useCallback } from 'react';
import { Play, Pause, RotateCcw, SkipForward, Timer, Coffee } from 'lucide-react';

interface Props {
  focusDuration?: number;
  onComplete: (actualMinutes: number, pauseCount: number) => void;
  stepTitle: string;
}

type Phase = 'focus' | 'break';

export const PomodoroTimer = ({ focusDuration = 25, onComplete, stepTitle }: Props) => {
  const [phase, setPhase] = useState<Phase>('focus');
  const [isRunning, setIsRunning] = useState(false);
  const [remainingSeconds, setRemainingSeconds] = useState(focusDuration * 60);
  const [totalSeconds, setTotalSeconds] = useState(focusDuration * 60);
  const [pauseCount, setPauseCount] = useState(0);
  const [completed, setCompleted] = useState(false);

  const startTimeRef = useRef<number | null>(null);
  const intervalRef = useRef<number | null>(null);

  const formatTime = useCallback((seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }, []);

  const clearTimer = useCallback(() => {
    if (intervalRef.current !== null) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, []);

  // Start / resume the timer
  const startTimer = useCallback(() => {
    if (intervalRef.current !== null) return;

    // Record start time on first play
    if (startTimeRef.current === null) {
      startTimeRef.current = Date.now();
    }

    setIsRunning(true);

    intervalRef.current = window.setInterval(() => {
      setRemainingSeconds((prev) => {
        if (prev <= 1) {
          clearTimer();
          setIsRunning(false);

          if (phase === 'focus') {
            // Focus complete — calculate actual time
            const actualMs = Date.now() - (startTimeRef.current ?? Date.now());
            const actualMinutes = Math.round(actualMs / 60000);
            setCompleted(true);
            onComplete(actualMinutes, pauseCount);
            return 0;
          } else {
            // Break complete — reset for next round (not auto-starting)
            return 0;
          }
        }
        return prev - 1;
      });
    }, 1000);
  }, [phase, pauseCount, onComplete, clearTimer]);

  // Pause the timer
  const pauseTimer = useCallback(() => {
    clearTimer();
    setIsRunning(false);
    setPauseCount((prev) => prev + 1);
  }, [clearTimer]);

  // Toggle play/pause
  const toggle = useCallback(() => {
    if (isRunning) {
      pauseTimer();
    } else {
      startTimer();
    }
  }, [isRunning, pauseTimer, startTimer]);

  // Reset everything
  const reset = useCallback(() => {
    clearTimer();
    setIsRunning(false);
    setPhase('focus');
    setRemainingSeconds(focusDuration * 60);
    setTotalSeconds(focusDuration * 60);
    setPauseCount(0);
    setCompleted(false);
    startTimeRef.current = null;
  }, [focusDuration, clearTimer]);

  // Start break after focus completes
  const startBreak = useCallback(() => {
    setPhase('break');
    const breakDuration = 5;
    setRemainingSeconds(breakDuration * 60);
    setTotalSeconds(breakDuration * 60);
    setIsRunning(false);
  }, []);

  // Skip break
  const skipBreak = useCallback(() => {
    clearTimer();
    setPhase('focus');
    setRemainingSeconds(focusDuration * 60);
    setTotalSeconds(focusDuration * 60);
    setIsRunning(false);
    setPauseCount(0);
    setCompleted(false);
    startTimeRef.current = null;
  }, [focusDuration, clearTimer]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      clearTimer();
    };
  }, [clearTimer]);

  // SVG ring calculations
  const radius = 80;
  const circumference = 2 * Math.PI * radius;
  const progress = totalSeconds > 0 ? ((totalSeconds - remainingSeconds) / totalSeconds) * 100 : 0;
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  return (
    <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-6 shadow-lg">
      {/* Header */}
      <div className="text-center mb-4">
        <h3 className="text-lg font-bold text-gray-800">
          {completed
            ? phase === 'break'
              ? '休息时间'
              : '专注完成！'
            : phase === 'break'
              ? '休息时间'
              : '专注时间'}
        </h3>
        <p className="text-sm text-gray-500 mt-1 truncate max-w-[200px] mx-auto" title={stepTitle}>
          {stepTitle}
        </p>
      </div>

      {/* Circular progress ring */}
      <div className="relative flex items-center justify-center mb-6">
        <svg className="w-48 h-48 -rotate-90" viewBox="0 0 192 192">
          {/* Background circle */}
          <circle
            cx="96"
            cy="96"
            r={radius}
            stroke="currentColor"
            strokeWidth="8"
            fill="none"
            className="text-gray-100"
          />
          {/* Progress circle */}
          <circle
            cx="96"
            cy="96"
            r={radius}
            strokeWidth="8"
            fill="none"
            strokeLinecap="round"
            className="transition-all duration-1000"
            style={{
              strokeDasharray: circumference,
              strokeDashoffset,
              stroke: phase === 'break'
                ? '#22c55e'
                : 'url(#focusGradient)',
              filter: phase === 'focus' && !completed
                ? 'drop-shadow(0 0 8px rgba(99, 102, 241, 0.4))'
                : 'none',
            }}
          />
          {/* Gradient definition for focus phase */}
          <defs>
            <linearGradient id="focusGradient" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#6366f1" />
              <stop offset="100%" stopColor="#9333ea" />
            </linearGradient>
          </defs>
        </svg>

        {/* Center content */}
        <div className="absolute flex flex-col items-center">
          <div className={`text-5xl font-bold ${
            phase === 'break' ? 'text-green-600' : 'text-gray-800'
          }`}>
            {formatTime(remainingSeconds)}
          </div>
          <div className="flex items-center gap-1.5 mt-2 text-sm text-gray-500">
            {phase === 'break' ? (
              <Coffee className="w-4 h-4" />
            ) : (
              <Timer className="w-4 h-4" />
            )}
            <span>
              {completed
                ? '已完成'
                : phase === 'break'
                  ? '休息中'
                  : isRunning
                    ? '专注中'
                    : '点击开始'}
            </span>
          </div>
        </div>
      </div>

      {/* Controls */}
      <div className="flex items-center justify-center gap-4">
        <button
          onClick={reset}
          className="p-3 rounded-full bg-gray-100 text-gray-600 hover:bg-gray-200 transition-all"
          title="重置"
        >
          <RotateCcw className="w-5 h-5" />
        </button>

        {!completed ? (
          <button
            onClick={toggle}
            className={`p-5 rounded-full transition-all ${
              phase === 'break'
                ? 'bg-green-500 text-white hover:bg-green-600 hover:shadow-lg hover:shadow-green-500/30'
                : 'bg-gradient-to-r from-indigo-500 to-purple-600 text-white hover:shadow-lg hover:shadow-indigo-500/30'
            }`}
          >
            {isRunning ? (
              <Pause className="w-6 h-6" />
            ) : (
              <Play className="w-6 h-6 ml-0.5" />
            )}
          </button>
        ) : (
          <button
            onClick={phase === 'focus' ? startBreak : skipBreak}
            className="p-5 rounded-full bg-gradient-to-r from-green-400 to-emerald-500 text-white hover:shadow-lg hover:shadow-green-500/30 transition-all"
            title={phase === 'focus' ? '开始休息' : '跳过休息'}
          >
            {phase === 'focus' ? (
              <Coffee className="w-6 h-6" />
            ) : (
              <SkipForward className="w-6 h-6" />
            )}
          </button>
        )}

        {/* Placeholder for layout symmetry */}
        {phase === 'break' && !completed ? (
          <button
            onClick={skipBreak}
            className="p-3 rounded-full bg-amber-100 text-amber-600 hover:bg-amber-200 transition-all"
            title="跳过休息"
          >
            <SkipForward className="w-5 h-5" />
          </button>
        ) : (
          <div className="w-11 h-11" />
        )}
      </div>

      {/* Pause count indicator */}
      {pauseCount > 0 && phase === 'focus' && (
        <div className="flex items-center justify-center gap-1.5 mt-4 text-sm text-amber-600">
          <Pause className="w-4 h-4" />
          <span>已暂停 {pauseCount} 次</span>
        </div>
      )}
    </div>
  );
};
