import { Step, Difficulty, ProfileSnapshot } from '../types';

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

const categorySteps: Record<string, string[]> = {
  '报告': ['理解实验目的', '整理实验数据', '撰写实验分析', '整理图片与说明', '检查格式与引用'],
  '写作': ['确定主题与结构', '收集素材', '列提纲', '撰写正文', '修改润色', '检查格式'],
  '编程': ['理解需求和设计', '编写代码框架', '实现核心逻辑', '测试调试', '优化和文档'],
  '复习': ['回顾课程内容', '整理笔记', '做练习题', '总结重点', '模拟测试'],
  '实验': ['理解实验目的', '准备实验器材', '进行实验操作', '记录实验数据', '分析实验结果', '撰写实验报告'],
};

const defaultSteps: Record<Difficulty, string[]> = {
  easy: ['分析任务要求', '收集必要资料', '执行任务', '检查结果'],
  medium: ['深入理解任务目标', '制定执行计划', '收集和整理资料', '逐步执行', '中期检查', '完善和优化'],
  hard: ['全面分析任务需求', '制定详细方案', '分解子任务', '收集相关资源', '逐步实现', '测试验证', '迭代优化', '最终检查'],
};

const stepMinutes: Record<Difficulty, { min: number; max: number }> = {
  easy: { min: 15, max: 25 },
  medium: { min: 20, max: 50 },
  hard: { min: 30, max: 60 },
};

export const simulateAISplit = async (
  taskId: string,
  title: string,
  description: string,
  difficulty: Difficulty,
  category: string,
  profile: ProfileSnapshot,
): Promise<Step[]> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const steps = categorySteps[category] || defaultSteps[difficulty];
      const range = stepMinutes[difficulty];
      const isWriting = category === '写作' || category === '报告';
      const timeFactor = isWriting ? profile.writingTimeFactor : 1.0;

      const result: Step[] = steps.map((stepTitle, index) => {
        const baseMinutes = Math.floor(Math.random() * (range.max - range.min) + range.min);
        const adjustedMinutes = Math.round(baseMinutes * timeFactor);
        const isKey = index === steps.length - 1 || (index === 0 && category === '编程');
        return {
          id: generateId(),
          taskId,
          title: stepTitle,
          estimatedMinutes: adjustedMinutes,
          actualMinutes: 0,
          status: 'pending',
          order: index + 1,
          isKey,
        };
      });
      resolve(result);
    }, 1500 + Math.random() * 800);
  });
};

export const getCategoryFromTitle = (title: string, description: string): string => {
  const text = `${title} ${description}`;
  if (text.includes('报告') || text.includes('report')) return '报告';
  if (text.includes('演讲') || text.includes('presentation')) return '写作';
  if (text.includes('论文') || text.includes('paper')) return '写作';
  if (text.includes('代码') || text.includes('编程') || text.includes('作业') && text.includes('算法')) return '编程';
  if (text.includes('实验') || text.includes('experiment')) return '实验';
  if (text.includes('复习') || text.includes('review')) return '复习';
  return '报告';
};
