import { Clock, AlertTriangle, Lightbulb } from 'lucide-react';

interface Props {
  totalEstimatedMinutes: number;
  availableMinutesToday: number;
  timeGap: number;
  taskCategory: string;
}

export const TimeGapAnalysis = ({
  totalEstimatedMinutes,
  availableMinutesToday,
  timeGap,
  taskCategory,
}: Props) => {
  const isDeficit = timeGap > 0;

  const getSuggestions = (): string[] => {
    const suggestions: string[] = [];

    if (timeGap > 60) {
      suggestions.push('建议分两天完成，今天先推进核心步骤');
    } else if (timeGap > 30) {
      suggestions.push('先完成必须交付部分，保留10分钟检查格式');
    } else if (timeGap > 0) {
      suggestions.push('时间紧凑，建议聚焦关键步骤');
    } else {
      suggestions.push('时间充裕，按推荐顺序推进即可');
    }

    if (taskCategory === '写作' || taskCategory === 'writing') {
      suggestions.push('写作类步骤建议提前安排');
    }

    if (totalEstimatedMinutes > 90) {
      suggestions.push('较长步骤建议拆成更小段');
    }

    suggestions.push('收尾检查建议固定预留10分钟');

    return suggestions;
  };

  const suggestions = getSuggestions();

  return (
    <div className="rounded-2xl bg-white/80 backdrop-blur-sm border border-gray-100 p-5">
      <div className="flex items-center gap-2 mb-4">
        <Clock className="w-5 h-5 text-indigo-500" />
        <h3 className="font-semibold text-gray-700">时间缺口分析</h3>
      </div>

      {/* 数据概览 */}
      <div className="grid grid-cols-3 gap-3 mb-4">
        <div className="rounded-xl bg-indigo-50 p-3 text-center">
          <p className="text-xs text-gray-400 mb-1">预计耗时</p>
          <p className="text-lg font-bold text-indigo-600">{totalEstimatedMinutes}</p>
          <p className="text-[10px] text-gray-400">分钟</p>
        </div>
        <div className="rounded-xl bg-green-50 p-3 text-center">
          <p className="text-xs text-gray-400 mb-1">今日可用</p>
          <p className="text-lg font-bold text-green-600">{availableMinutesToday}</p>
          <p className="text-[10px] text-gray-400">分钟</p>
        </div>
        <div className={`rounded-xl p-3 text-center ${isDeficit ? 'bg-red-50' : 'bg-green-50'}`}>
          <p className="text-xs text-gray-400 mb-1">时间缺口</p>
          <p className={`text-lg font-bold ${isDeficit ? 'text-red-600' : 'text-green-600'}`}>
            {isDeficit ? `+${timeGap}` : `${timeGap}`}
          </p>
          <p className="text-[10px] text-gray-400">{isDeficit ? '不足' : '充裕'}</p>
        </div>
      </div>

      {/* 风险提示 */}
      {isDeficit && (
        <div className="flex items-start gap-2 rounded-xl bg-amber-50 border border-amber-100 p-3 mb-4">
          <AlertTriangle className="w-4 h-4 text-amber-500 flex-shrink-0 mt-0.5" />
          <p className="text-xs text-amber-700">
            今日可用时间不足以完成全部步骤，还差 {timeGap} 分钟
          </p>
        </div>
      )}

      {/* 建议列表 */}
      <div className="space-y-2">
        <div className="flex items-center gap-1.5 mb-1">
          <Lightbulb className="w-4 h-4 text-amber-500" />
          <span className="text-sm font-medium text-gray-600">温和建议</span>
        </div>
        {suggestions.map((suggestion, index) => (
          <div
            key={index}
            className="flex items-start gap-2 rounded-lg bg-gray-50 px-3 py-2"
          >
            <span className="w-5 h-5 rounded-full bg-indigo-100 text-indigo-600 text-xs flex items-center justify-center flex-shrink-0 mt-0.5">
              {index + 1}
            </span>
            <p className="text-sm text-gray-600">{suggestion}</p>
          </div>
        ))}
      </div>
    </div>
  );
};
