import { useState, useMemo } from 'react';
import { Plus, User, GraduationCap, AlertTriangle, Clock, ArrowRight } from 'lucide-react';
import { Task } from '../types';
import { useTasksStore } from '../stores/appStore';
import { useProfileStore } from '../stores/profileStore';
import { TaskDetail } from '../components/TaskDetail/TaskDetail';
import { CreateDDLModal } from '../components/CreateDDL/CreateDDLModal';
import { UserProfilePanel } from '../components/UserProfile/UserProfilePanel';
import { CourseTimeline } from '../components/Dashboard/CourseTimeline';
import { generateNowSuggestion } from '../utils/suggestionEngine';
import { assessAllRisks } from '../utils/riskEngine';

export default function Home() {
  const tasks = useTasksStore((s) => s.tasks);
  const profile = useProfileStore((s) => s.profile);
  const courses = useProfileStore((s) => s.courses);
  const explicitPreference = useProfileStore((s) => s.explicitPreference);
  const profileSnapshot = useProfileStore((s) => s.profileSnapshot);

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);

  const activeTasks = useTasksStore((s) => s.tasks);
  const currentSelectedTask = selectedTask
    ? activeTasks.find((t) => t.id === selectedTask.id) || selectedTask
    : null;

  const risks = useMemo(
    () => assessAllRisks(tasks, courses, profileSnapshot),
    [tasks, courses, profileSnapshot],
  );

  const suggestion = useMemo(
    () => generateNowSuggestion(tasks, courses, explicitPreference, profileSnapshot),
    [tasks, courses, explicitPreference, profileSnapshot],
  );

  const highRiskTasks = risks.filter((r) => r.level === 'high' && tasks.find(t => t.id === r.taskId)?.progress === 0);
  const hasEmergency = highRiskTasks.length > 0;

  const pendingTasks = tasks.filter((t) => t.status !== 'completed');
  const completedTasks = tasks.filter((t) => t.status === 'completed');

  const handleTaskCreated = () => {
    const updatedTasks = useTasksStore.getState().tasks;
    if (updatedTasks.length > 0) {
      setSelectedTask(updatedTasks[updatedTasks.length - 1]);
    }
  };

  const formatDeadline = (deadline: Date) => {
    const now = new Date();
    const diff = deadline.getTime() - now.getTime();
    const hours = Math.floor(diff / (1000 * 60 * 60));
    if (hours < 0) return '已过期';
    if (hours < 24) return `${hours}小时后`;
    const days = Math.floor(hours / 24);
    return `${days}天后`;
  };

  const formatDeadlineDetail = (deadline: Date) => {
    const today = new Date();
    const d = new Date(deadline);
    const isToday = d.toDateString() === today.toDateString();
    const hours = d.getHours().toString().padStart(2, '0');
    const mins = d.getMinutes().toString().padStart(2, '0');
    if (isToday) return `今晚 ${hours}:${mins}`;
    const tomorrow = new Date(today);
    tomorrow.setDate(today.getDate() + 1);
    if (d.toDateString() === tomorrow.toDateString()) return `明天 ${hours}:${mins}`;
    return `${d.getMonth() + 1}/${d.getDate()} ${hours}:${mins}`;
  };

  const getCurrentSuggestedStep = (task: Task) => {
    const pendingSteps = task.steps.filter((s) => s.status === 'pending');
    if (pendingSteps.length === 0) return null;
    return pendingSteps[0];
  };

  const getRiskBadge = (taskId: string) => {
    const r = risks.find((x) => x.taskId === taskId);
    if (!r) return { label: '低风险', color: 'bg-green-100 text-green-700' };
    if (r.level === 'high') return { label: '高风险', color: 'bg-red-100 text-red-700' };
    if (r.level === 'medium') return { label: '中风险', color: 'bg-amber-100 text-amber-700' };
    return { label: '低风险', color: 'bg-green-100 text-green-700' };
  };

  const handleTakeSuggestion = () => {
    if (suggestion) {
      const task = tasks.find((t) => t.id === suggestion.taskId);
      if (task) setSelectedTask(task);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-indigo-50/20 to-purple-50/20">
      <div className="fixed top-0 left-0 right-0 h-52 bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 opacity-[0.08] pointer-events-none" />

      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
        {/* Header */}
        <header className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white font-bold shadow-md shadow-indigo-500/25">
              D
            </div>
            <div>
              <h1 className="text-xl font-bold text-white drop-shadow-sm">College DDL</h1>
              <p className="text-xs text-white/70">AI 学习任务推进系统</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setIsProfileOpen(true)}
              className="flex items-center gap-2 px-3 py-2 rounded-xl bg-white/20 backdrop-blur-md hover:bg-white/30 transition-all text-white text-sm"
            >
              <div className="w-6 h-6 rounded-full bg-white/30 flex items-center justify-center text-xs">
                {profile.avatar}
              </div>
              <span className="font-medium hidden sm:inline text-sm">{profile.name}</span>
              <User className="w-4 h-4" />
            </button>
            <button
              onClick={() => setIsCreateModalOpen(true)}
              className="flex items-center gap-1.5 px-4 py-2 rounded-xl bg-white text-indigo-600 text-sm font-semibold hover:shadow-lg hover:shadow-indigo-500/25 transition-all"
            >
              <Plus className="w-4 h-4" />
              <span className="hidden sm:inline">新建 DDL</span>
            </button>
          </div>
        </header>

        {/* Emergency / Now Suggestion */}
        <div className="mb-4">
          {hasEmergency ? (
            <div className="bg-gradient-to-r from-red-500 via-rose-500 to-orange-500 rounded-2xl p-5 text-white shadow-lg shadow-red-500/25">
              <div className="flex items-start gap-3">
                <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center flex-shrink-0">
                  <AlertTriangle className="w-5 h-5" />
                </div>
                <div className="flex-1">
                  <div className="text-xs font-medium text-white/80 mb-1">紧急提醒</div>
                  <h2 className="text-lg font-bold mb-2">
                    {highRiskTasks[0] && (() => {
                      const t = tasks.find(tt => tt.id === highRiskTasks[0].taskId);
                      const risk = highRiskTasks[0];
                      const firstStep = t?.steps.find(s => s.status === 'pending');
                      return (
                        <>
                          {t?.title} 将在 {t ? formatDeadlineDetail(t.deadline) : ''} 截止，预计还需 {risk.timeGap > 0 ? `${risk.timeGap}` : `${-risk.totalEstimatedMinutes}`} 分钟。
                          {firstStep && `建议现在先完成"${firstStep.title}"。`}
                        </>
                      );
                    })()}
                  </h2>
                  <button
                    onClick={() => {
                      if (highRiskTasks[0]) {
                        const t = tasks.find(tt => tt.id === highRiskTasks[0].taskId);
                        if (t) setSelectedTask(t);
                      }
                    }}
                    className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-white text-red-600 text-sm font-semibold hover:shadow-md transition-all"
                  >
                    立即开始
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>
          ) : suggestion ? (
            <div className="bg-gradient-to-r from-indigo-500 to-purple-600 rounded-2xl p-5 text-white shadow-lg shadow-indigo-500/25">
              <div className="flex items-start gap-3">
                <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center flex-shrink-0">
                  <Clock className="w-5 h-5" />
                </div>
                <div className="flex-1">
                  <div className="text-xs font-medium text-white/80 mb-1">现在建议</div>
                  <h2 className="text-lg font-bold mb-1">{suggestion.text}</h2>
                  <p className="text-sm text-white/70">{suggestion.reason}</p>
                </div>
                <button
                  onClick={handleTakeSuggestion}
                  className="px-4 py-2 rounded-xl bg-white/20 hover:bg-white/30 text-white text-sm font-medium transition-all"
                >
                  去看看
                </button>
              </div>
            </div>
          ) : null}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
          {/* Left: Today's Courses */}
          <div className="lg:col-span-3">
            <div className="bg-white/80 backdrop-blur-md rounded-2xl p-4 shadow-sm mb-4">
              <div className="flex items-center gap-2 mb-3">
                <GraduationCap className="w-4 h-4 text-indigo-500" />
                <h2 className="text-sm font-bold text-gray-700">今日课表</h2>
              </div>
              <CourseTimeline courses={courses} />
            </div>
          </div>

          {/* Middle: DDL List (main thread) */}
          <div className="lg:col-span-4">
            <div className="bg-white/80 backdrop-blur-md rounded-2xl p-4 shadow-sm h-[calc(100vh-240px)] overflow-y-auto">
              <div className="flex items-center justify-between mb-3">
                <h2 className="text-sm font-bold text-gray-700">今日 DDL</h2>
                <span className="text-xs text-gray-400">共 {pendingTasks.length} 个待完成</span>
              </div>

              {pendingTasks.length > 0 ? (
                <div className="space-y-3">
                  {pendingTasks.map((task) => {
                    const risk = getRiskBadge(task.id);
                    const currentStep = getCurrentSuggestedStep(task);
                    return (
                      <div
                        key={task.id}
                        onClick={() => setSelectedTask(task)}
                        className={`p-4 rounded-xl cursor-pointer transition-all border ${
                          selectedTask?.id === task.id
                            ? 'bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-transparent shadow-lg shadow-indigo-500/20'
                            : 'bg-white hover:shadow-md hover:-translate-y-0.5 border-gray-100'
                        }`}
                      >
                        <div className="flex items-start justify-between mb-2">
                          <h3 className={`font-bold text-base flex-1 ${
                            selectedTask?.id === task.id ? 'text-white' : 'text-gray-800'
                          }`}>
                            {task.title}
                          </h3>
                        </div>

                        <div className="flex items-center gap-2 mb-2">
                          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                            selectedTask?.id === task.id ? 'bg-white/20 text-white' : risk.color
                          }`}>
                            {risk.label}
                          </span>
                          <span className={`text-xs px-2 py-0.5 rounded-full ${
                            selectedTask?.id === task.id ? 'bg-white/20 text-white' : 'bg-indigo-50 text-indigo-600'
                          }`}>
                            {task.category}
                          </span>
                        </div>

                        <div className={`text-xs mb-2 ${
                          selectedTask?.id === task.id ? 'text-white/80' : 'text-gray-500'
                        }`}>
                          <span>DDL：{formatDeadlineDetail(task.deadline)}</span>
                        </div>

                        {/* Progress bar */}
                        <div className="mb-2">
                          <div className="flex items-center justify-between text-xs mb-1">
                            <span className={selectedTask?.id === task.id ? 'text-white/70' : 'text-gray-400'}>
                              进度
                            </span>
                            <span className={`font-medium ${
                              selectedTask?.id === task.id ? 'text-white' : 'text-gray-600'
                            }`}>
                              {task.progress}%
                            </span>
                          </div>
                          <div className={`h-2 rounded-full overflow-hidden ${
                            selectedTask?.id === task.id ? 'bg-white/20' : 'bg-gray-100'
                          }`}>
                            <div
                              className={`h-full rounded-full transition-all duration-500 ${
                                selectedTask?.id === task.id
                                  ? 'bg-white'
                                  : 'bg-gradient-to-r from-indigo-500 to-purple-600'
                              }`}
                              style={{ width: `${task.progress}%` }}
                            />
                          </div>
                        </div>

                        {currentStep && (
                          <div className={`text-xs flex items-center gap-1 ${
                            selectedTask?.id === task.id ? 'text-white/80' : 'text-indigo-600'
                          }`}>
                            <span className="opacity-70">当前建议：</span>
                            <span className="font-medium">{currentStep.title}</span>
                            <span className="opacity-70">（{currentStep.estimatedMinutes}分）</span>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div className="text-center py-10 text-gray-400 text-sm">
                  今日 DDL 全部完成！
                </div>
              )}

              {completedTasks.length > 0 && (
                <div className="mt-6 pt-4 border-t border-gray-100">
                  <h3 className="text-xs font-bold text-gray-400 mb-2">已完成</h3>
                  <div className="space-y-2 opacity-60">
                    {completedTasks.map((task) => (
                      <div
                        key={task.id}
                        onClick={() => setSelectedTask(task)}
                        className="p-3 rounded-lg bg-gray-50 cursor-pointer hover:bg-gray-100"
                      >
                        <h4 className="font-medium text-sm text-gray-500 line-through truncate">{task.title}</h4>
                        <div className="text-xs text-gray-400 mt-0.5">已完成</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Right: Task Detail */}
          <div className="lg:col-span-5">
            {currentSelectedTask ? (
              <div className="bg-white/80 backdrop-blur-md rounded-2xl p-4 shadow-sm h-[calc(100vh-240px)] overflow-y-auto">
                <TaskDetail task={currentSelectedTask} />
              </div>
            ) : (
              <div className="bg-white/80 backdrop-blur-md rounded-2xl p-5 shadow-sm h-[calc(100vh-240px)] flex flex-col items-center justify-center text-center">
                <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-indigo-100 to-purple-100 flex items-center justify-center mb-4">
                  <span className="text-3xl">📚</span>
                </div>
                <h3 className="text-base font-bold text-gray-700 mb-1">选择一个 DDL 开始</h3>
                <p className="text-gray-400 text-sm mb-4 max-w-xs">
                  从左侧 DDL 列表中选择，或点击右上角新建
                </p>
                <button
                  onClick={() => setIsCreateModalOpen(true)}
                  className="px-5 py-2 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600 text-white text-sm font-semibold hover:shadow-lg hover:shadow-indigo-500/25 transition-all"
                >
                  新建 DDL
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <CreateDDLModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onTaskCreated={handleTaskCreated}
      />

      <UserProfilePanel
        isOpen={isProfileOpen}
        onClose={() => setIsProfileOpen(false)}
      />
    </div>
  );
}
