import { useState } from 'react';
import { X, Sparkles } from 'lucide-react';
import { Difficulty, Importance } from '../../types';
import { useTasksStore } from '../../stores/appStore';
import { useProfileStore } from '../../stores/profileStore';
import { simulateAISplit, getCategoryFromTitle } from '../../utils/aiSplit';

interface CreateDDLModalProps {
  isOpen: boolean;
  onClose: () => void;
  onTaskCreated: () => void;
}

export const CreateDDLModal = ({ isOpen, onClose, onTaskCreated }: CreateDDLModalProps) => {
  const addTask = useTasksStore((s) => s.addTask);
  const setTaskSteps = useTasksStore((s) => s.setTaskSteps);
  const profileSnapshot = useProfileStore((s) => s.profileSnapshot);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [deadline, setDeadline] = useState('');
  const [difficulty, setDifficulty] = useState<Difficulty>('medium');
  const [importance, setImportance] = useState<Importance>('medium');
  const [isProcessing, setIsProcessing] = useState(false);

  const handleSubmit = async () => {
    if (!title || !deadline) return;
    setIsProcessing(true);

    const category = getCategoryFromTitle(title, description);

    addTask({
      title,
      description,
      deadline: new Date(deadline),
      difficulty,
      importance,
      category,
    });

    const lastTask = useTasksStore.getState().tasks[useTasksStore.getState().tasks.length - 1];
    const steps = await simulateAISplit(lastTask.id, title, description, difficulty, category, profileSnapshot);
    setTaskSteps(lastTask.id, steps);

    setIsProcessing(false);
    onTaskCreated();
    onClose();
    resetForm();
  };

  const resetForm = () => {
    setTitle('');
    setDescription('');
    setDeadline('');
    setDifficulty('medium');
    setImportance('medium');
  };

  const handleClose = () => {
    onClose();
    resetForm();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/30 backdrop-blur-sm" onClick={handleClose} />
      <div className="relative w-full max-w-lg bg-white rounded-2xl shadow-2xl overflow-hidden">
        <div className="bg-gradient-to-r from-indigo-500 to-purple-600 px-6 py-4">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-bold text-white">新建 DDL</h2>
            <button onClick={handleClose} className="p-1 rounded-full hover:bg-white/20 transition-colors">
              <X className="w-5 h-5 text-white" />
            </button>
          </div>
        </div>
        <div className="p-6 space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">任务标题 <span className="text-red-500">*</span></label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="例如：摄影实验报告"
              className="w-full px-4 py-2.5 rounded-xl border border-gray-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 outline-none transition-all"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">任务描述</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="描述任务的具体内容..."
              rows={2}
              className="w-full px-4 py-2.5 rounded-xl border border-gray-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 outline-none transition-all resize-none"
            />
          </div>
          <div className="grid grid-cols-3 gap-3">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">截止时间 <span className="text-red-500">*</span></label>
              <input
                type="datetime-local"
                value={deadline}
                onChange={(e) => setDeadline(e.target.value)}
                className="w-full px-3 py-2.5 rounded-xl border border-gray-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 outline-none transition-all text-sm"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">重要等级</label>
              <select
                value={importance}
                onChange={(e) => setImportance(e.target.value as Importance)}
                className="w-full px-3 py-2.5 rounded-xl border border-gray-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 outline-none transition-all bg-white text-sm"
              >
                <option value="high">高等</option>
                <option value="medium">中等</option>
                <option value="low">低等</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">难度等级</label>
              <select
                value={difficulty}
                onChange={(e) => setDifficulty(e.target.value as Difficulty)}
                className="w-full px-3 py-2.5 rounded-xl border border-gray-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 outline-none transition-all bg-white text-sm"
              >
                <option value="easy">简单</option>
                <option value="medium">中等</option>
                <option value="hard">困难</option>
              </select>
            </div>
          </div>
          <button
            onClick={handleSubmit}
            disabled={!title || !deadline || isProcessing}
            className="w-full px-4 py-3 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600 text-white font-medium hover:shadow-lg hover:shadow-indigo-500/25 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            {isProcessing ? (
              <span className="flex items-center justify-center gap-2">
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                AI 分析拆分中...
              </span>
            ) : (
              <span className="flex items-center justify-center gap-2">
                <Sparkles className="w-4 h-4" />
                创建并智能拆分
              </span>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};
