import { Clock, Pause, TrendingUp, Eye } from 'lucide-react';
import { BehaviorRecord, ProfileSnapshot } from '../../types';

interface Props {
  record: BehaviorRecord;
  profile: ProfileSnapshot;
}

function isWritingCategory(category: string): boolean {
  return category === '写作' || category === '报告' || category === 'writing';
}

function getObservation(record: BehaviorRecord): string {
  const overTime = record.actualMinutes > record.estimatedMinutes * 1.3;

  if (isWritingCategory(record.category) && overTime) {
    return '写作类步骤建议提前安排';
  }

  if (overTime) {
    return '这类步骤建议预留更充足的缓冲时间';
  }

  if (record.pauseCount >= 2) {
    return '较长步骤建议拆成更小段';
  }

  if (isWritingCategory(record.category)) {
    return '下次遇到报告类任务时，College DDL 会优先推荐"整理素材"或"列提纲"作为启动步骤';
  }

  return '保持专注，按节奏推进';
}

export const BehaviorRecordCard = ({ record, profile }: Props) => {
  const observation = getObservation(record);
  const timeDiff = record.actualMinutes - record.estimatedMinutes;
  const overTime = timeDiff > 0;

  return (
    <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-6">
      <div className="flex items-center gap-2 mb-5">
        <Eye className="w-5 h-5 text-indigo-500" />
        <h3 className="font-semibold text-gray-800">行为记录</h3>
      </div>

      {/* Metrics */}
      <div className="grid grid-cols-3 gap-3 mb-5">
        <div className="bg-gray-50 rounded-xl p-3 text-center">
          <div className="flex items-center justify-center gap-1 mb-1.5">
            <Clock className="w-3.5 h-3.5 text-gray-400" />
            <span className="text-xs text-gray-400">预计耗时</span>
          </div>
          <span className="text-lg font-bold text-gray-700">
            {record.estimatedMinutes}
          </span>
          <span className="text-xs text-gray-400 ml-0.5">分钟</span>
        </div>

        <div className="bg-gray-50 rounded-xl p-3 text-center">
          <div className="flex items-center justify-center gap-1 mb-1.5">
            <TrendingUp className="w-3.5 h-3.5 text-gray-400" />
            <span className="text-xs text-gray-400">实际耗时</span>
          </div>
          <span className={`text-lg font-bold ${overTime ? 'text-amber-600' : 'text-green-600'}`}>
            {record.actualMinutes}
          </span>
          <span className="text-xs text-gray-400 ml-0.5">分钟</span>
        </div>

        <div className="bg-gray-50 rounded-xl p-3 text-center">
          <div className="flex items-center justify-center gap-1 mb-1.5">
            <Pause className="w-3.5 h-3.5 text-gray-400" />
            <span className="text-xs text-gray-400">暂停次数</span>
          </div>
          <span className={`text-lg font-bold ${record.pauseCount >= 2 ? 'text-amber-600' : 'text-gray-700'}`}>
            {record.pauseCount}
          </span>
          <span className="text-xs text-gray-400 ml-0.5">次</span>
        </div>
      </div>

      {/* Time difference indicator */}
      {timeDiff !== 0 && (
        <div className={`flex items-center justify-center gap-1.5 mb-4 text-sm ${
          overTime ? 'text-amber-600' : 'text-green-600'
        }`}>
          <TrendingUp className="w-4 h-4" />
          <span>
            {overTime
              ? `比预计多用了 ${timeDiff} 分钟`
              : `比预计少用了 ${Math.abs(timeDiff)} 分钟`}
          </span>
        </div>
      )}

      {/* System observation */}
      <div className="p-4 rounded-xl bg-indigo-50 border border-indigo-100">
        <div className="flex items-start gap-2">
          <SparkleIcon className="w-4 h-4 text-indigo-500 mt-0.5 flex-shrink-0" />
          <div>
            <p className="text-xs font-medium text-indigo-600 mb-1">系统观察</p>
            <p className="text-sm text-indigo-800">{observation}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

function SparkleIcon({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M12 2l1.09 3.09L16 6l-2.91.91L12 10l-1.09-3.09L8 6l2.91-.91L12 2z" />
      <path d="M5 14l.64 1.64L7 16l-1.36.36L5 18l-.64-1.64L3 16l1.36-.36L5 14z" />
      <path d="M19 14l.64 1.64L21 16l-1.36.36L19 18l-.64-1.64L17 16l1.36-.36L19 14z" />
    </svg>
  );
}
