import { ArrowRight, TrendingUp, X } from 'lucide-react';
import { ProfileSnapshot } from '../../types';

interface Props {
  before: ProfileSnapshot;
  after: ProfileSnapshot;
  onClose: () => void;
}

interface MetricChange {
  label: string;
  beforeText: string;
  afterText: string;
  changed: boolean;
}

function buildMetrics(before: ProfileSnapshot, after: ProfileSnapshot): MetricChange[] {
  const metrics: MetricChange[] = [];

  const writingChanged = before.writingTimeFactor !== after.writingTimeFactor;
  metrics.push({
    label: '写作类任务估时系数',
    beforeText: `×${before.writingTimeFactor}`,
    afterText: `×${after.writingTimeFactor}`,
    changed: writingChanged,
  });

  const pomodoroChanged = before.recommendedPomodoroMinutes !== after.recommendedPomodoroMinutes;
  metrics.push({
    label: '推荐番茄钟',
    beforeText: `${before.recommendedPomodoroMinutes}分钟`,
    afterText: `${after.recommendedPomodoroMinutes}分钟`,
    changed: pomodoroChanged,
  });

  const startChanged = before.startWithLowPressure !== after.startWithLowPressure;
  metrics.push({
    label: '启动步骤',
    beforeText: before.startWithLowPressure
      ? '优先推荐低压力步骤'
      : '系统推荐最重要步骤',
    afterText: after.startWithLowPressure
      ? '优先推荐低压力步骤'
      : '系统推荐最重要步骤',
    changed: startChanged,
  });

  const bufferChanged = before.checkBufferMinutes !== after.checkBufferMinutes;
  metrics.push({
    label: '检查缓冲时间',
    beforeText: `${before.checkBufferMinutes}分钟`,
    afterText: `${after.checkBufferMinutes}分钟`,
    changed: bufferChanged,
  });

  const pauseFactorChanged = before.longStepPauseFactor !== after.longStepPauseFactor;
  metrics.push({
    label: '长步骤暂停系数',
    beforeText: `×${before.longStepPauseFactor}`,
    afterText: `×${after.longStepPauseFactor}`,
    changed: pauseFactorChanged,
  });

  return metrics;
}

export const ProfileComparisonCard = ({ before, after, onClose }: Props) => {
  const metrics = buildMetrics(before, after);
  const hasAnyChange = metrics.some((m) => m.changed);

  return (
    <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-6 relative">
      {/* Close button */}
      <button
        onClick={onClose}
        className="absolute top-4 right-4 p-1.5 rounded-lg text-gray-400 hover:text-gray-600 hover:bg-gray-100 transition-all"
      >
        <X className="w-4 h-4" />
      </button>

      <div className="flex items-center gap-2 mb-5">
        <TrendingUp className="w-5 h-5 text-indigo-500" />
        <h3 className="font-semibold text-gray-800">画像更新</h3>
      </div>

      {!hasAnyChange ? (
        <p className="text-sm text-gray-500 text-center py-4">
          本次行为暂未触发画像调整，继续保持！
        </p>
      ) : (
        <>
          {/* Two-column header */}
          <div className="grid grid-cols-[1fr_auto_1fr] gap-2 mb-3 px-1">
            <span className="text-xs font-medium text-gray-400 text-center">更新前</span>
            <span className="w-5" />
            <span className="text-xs font-medium text-indigo-500 text-center">更新后</span>
          </div>

          {/* Metrics rows */}
          <div className="space-y-2 mb-5">
            {metrics.map((metric) => (
              <div
                key={metric.label}
                className={`p-3 rounded-xl ${
                  metric.changed
                    ? 'bg-indigo-50 border border-indigo-100'
                    : 'bg-gray-50'
                }`}
              >
                <p className={`text-xs mb-1.5 ${
                  metric.changed ? 'text-indigo-600 font-medium' : 'text-gray-400'
                }`}>
                  {metric.label}
                </p>
                <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-2">
                  <span className={`text-sm text-right ${
                    metric.changed ? 'text-gray-400' : 'text-gray-600'
                  }`}>
                    {metric.beforeText}
                  </span>
                  <span className="flex items-center justify-center">
                    <ArrowRight
                      className={`w-4 h-4 ${
                        metric.changed ? 'text-indigo-500' : 'text-gray-300'
                      }`}
                    />
                  </span>
                  <span className={`text-sm ${
                    metric.changed
                      ? 'text-indigo-700 font-semibold'
                      : 'text-gray-600'
                  }`}>
                    {metric.afterText}
                  </span>
                </div>
              </div>
            ))}
          </div>

          {/* Summary */}
          <div className="p-4 rounded-xl bg-gradient-to-r from-indigo-50 to-purple-50 border border-indigo-100">
            <p className="text-sm text-indigo-800 text-center">
              College DDL 已根据你的真实行为校准下一次建议。
            </p>
          </div>
        </>
      )}
    </div>
  );
};
