import { useState } from 'react';
import {
  X, Edit2, Check, User, Settings, Eye, TrendingUp,
  ThumbsUp, ThumbsDown, MinusCircle, ArrowRight,
} from 'lucide-react';
import { useProfileStore } from '../../stores/profileStore';

interface Props {
  isOpen: boolean;
  onClose: () => void;
}

const pushPreferenceOptions: { value: 'system' | 'easiest' | 'shortest' | 'most_important' | 'manual'; label: string }[] = [
  { value: 'system', label: '按系统推荐' },
  { value: 'easiest', label: '先做最简单的' },
  { value: 'shortest', label: '先做最短的' },
  { value: 'most_important', label: '先做最重要的' },
  { value: 'manual', label: '手动排序' },
];

const reminderStyleOptions: { value: 'gentle' | 'normal' | 'none'; label: string }[] = [
  { value: 'gentle', label: '温和提醒' },
  { value: 'normal', label: '普通提醒' },
  { value: 'none', label: '不提醒' },
];

type TabKey = 'explicit' | 'implicit';

export const UserProfilePanel = ({ isOpen, onClose }: Props) => {
  const {
    profile, explicitPreference, implicitObservations,
    profileSnapshot, previousSnapshot, showComparison,
    setExplicitPreference, setObservationFeedback, updateProfile, setShowComparison,
  } = useProfileStore();

  const [activeTab, setActiveTab] = useState<TabKey>('explicit');
  const [isEditingName, setIsEditingName] = useState(false);
  const [editName, setEditName] = useState(profile.name);

  if (!isOpen) return null;

  const handleSaveName = () => {
    updateProfile({ name: editName });
    setIsEditingName(false);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-black/30 backdrop-blur-sm"
        onClick={onClose}
      />

      <div className="relative w-full max-w-lg bg-white rounded-2xl shadow-2xl overflow-hidden max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="bg-gradient-to-r from-indigo-500 to-purple-600 px-6 py-6 text-center relative shrink-0">
          <button
            onClick={onClose}
            className="absolute right-4 top-4 p-1 rounded-full hover:bg-white/20 transition-colors"
          >
            <X className="w-5 h-5 text-white" />
          </button>

          <div className="w-16 h-16 mx-auto mb-3 rounded-full bg-white/20 flex items-center justify-center">
            <User className="w-8 h-8 text-white" />
          </div>

          {isEditingName ? (
            <div className="flex items-center justify-center gap-2">
              <input
                type="text"
                value={editName}
                onChange={(e) => setEditName(e.target.value)}
                className="px-3 py-1 rounded-lg text-white bg-white/20 border border-white/30 focus:outline-none focus:border-white text-center"
              />
              <button onClick={handleSaveName} className="p-1 rounded-full hover:bg-white/20">
                <Check className="w-4 h-4 text-white" />
              </button>
            </div>
          ) : (
            <div className="flex items-center justify-center gap-2">
              <h2 className="text-xl font-bold text-white">{profile.name}</h2>
              <button
                onClick={() => { setEditName(profile.name); setIsEditingName(true); }}
                className="p-1 rounded-full hover:bg-white/20"
              >
                <Edit2 className="w-4 h-4 text-white/70" />
              </button>
            </div>
          )}

          <p className="text-white/70 text-sm mt-1">
            🔥 坚持 {profile.streakDays} 天
          </p>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200 shrink-0">
          <button
            onClick={() => setActiveTab('explicit')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-sm font-medium transition-colors ${
              activeTab === 'explicit'
                ? 'text-indigo-600 border-b-2 border-indigo-600'
                : 'text-gray-500 hover:text-gray-700'
            }`}
          >
            <Settings className="w-4 h-4" />
            显性偏好
          </button>
          <button
            onClick={() => setActiveTab('implicit')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-sm font-medium transition-colors ${
              activeTab === 'implicit'
                ? 'text-indigo-600 border-b-2 border-indigo-600'
                : 'text-gray-500 hover:text-gray-700'
            }`}
          >
            <Eye className="w-4 h-4" />
            隐性画像
          </button>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-5">
          {activeTab === 'explicit' && (
            <>
              {/* 推进偏好 */}
              <div>
                <h3 className="font-semibold text-gray-700 mb-3">推进偏好</h3>
                <div className="space-y-2">
                  {pushPreferenceOptions.map((opt) => (
                    <label
                      key={opt.value}
                      className={`flex items-center gap-3 px-4 py-2.5 rounded-xl border cursor-pointer transition-all ${
                        explicitPreference.pushPreference === opt.value
                          ? 'border-indigo-500 bg-indigo-50 text-indigo-700'
                          : 'border-gray-200 hover:border-indigo-200 text-gray-600'
                      }`}
                    >
                      <input
                        type="radio"
                        name="pushPreference"
                        value={opt.value}
                        checked={explicitPreference.pushPreference === opt.value}
                        onChange={() => setExplicitPreference({ pushPreference: opt.value })}
                        className="accent-indigo-600"
                      />
                      <span className="text-sm">{opt.label}</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* 番茄钟偏好 */}
              <div>
                <h3 className="font-semibold text-gray-700 mb-3">番茄钟偏好（分钟）</h3>
                <div className="flex items-center gap-3">
                  <input
                    type="number"
                    min={15}
                    max={45}
                    value={explicitPreference.pomodoroDuration}
                    onChange={(e) => {
                      const val = Math.min(45, Math.max(15, Number(e.target.value) || 15));
                      setExplicitPreference({ pomodoroDuration: val });
                    }}
                    className="w-24 px-4 py-2 rounded-xl border border-gray-200 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 outline-none"
                  />
                  <span className="text-sm text-gray-500">范围：15 - 45 分钟</span>
                </div>
              </div>

              {/* 提醒方式 */}
              <div>
                <h3 className="font-semibold text-gray-700 mb-3">提醒方式</h3>
                <div className="space-y-2">
                  {reminderStyleOptions.map((opt) => (
                    <label
                      key={opt.value}
                      className={`flex items-center gap-3 px-4 py-2.5 rounded-xl border cursor-pointer transition-all ${
                        explicitPreference.reminderStyle === opt.value
                          ? 'border-indigo-500 bg-indigo-50 text-indigo-700'
                          : 'border-gray-200 hover:border-indigo-200 text-gray-600'
                      }`}
                    >
                      <input
                        type="radio"
                        name="reminderStyle"
                        value={opt.value}
                        checked={explicitPreference.reminderStyle === opt.value}
                        onChange={() => setExplicitPreference({ reminderStyle: opt.value })}
                        className="accent-indigo-600"
                      />
                      <span className="text-sm">{opt.label}</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* 是否接受系统推荐 */}
              <div>
                <h3 className="font-semibold text-gray-700 mb-3">是否接受系统推荐</h3>
                <div className="flex items-center justify-between px-4 py-3 rounded-xl border border-gray-200">
                  <span className="text-sm text-gray-600">接受系统推荐</span>
                  <button
                    onClick={() => setExplicitPreference({ acceptSuggestion: !explicitPreference.acceptSuggestion })}
                    className={`relative w-12 h-6 rounded-full transition-colors ${
                      explicitPreference.acceptSuggestion ? 'bg-indigo-500' : 'bg-gray-300'
                    }`}
                  >
                    <span
                      className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white shadow transition-transform ${
                        explicitPreference.acceptSuggestion ? 'translate-x-6' : 'translate-x-0'
                      }`}
                    />
                  </button>
                </div>
              </div>
            </>
          )}

          {activeTab === 'implicit' && (
            <>
              {implicitObservations.length === 0 && (
                <p className="text-center text-gray-400 py-8">暂无隐性观察数据</p>
              )}
              {implicitObservations.map((obs) => {
                const hasFeedback = obs.feedback !== null;
                return (
                  <div
                    key={obs.id}
                    className={`rounded-xl border p-4 transition-opacity ${
                      hasFeedback ? 'border-gray-200 opacity-50' : 'border-gray-200'
                    }`}
                  >
                    <div className="flex items-start justify-between mb-2">
                      <span className="text-sm font-medium text-gray-800">{obs.content}</span>
                      <span className="text-xs text-gray-400 ml-2 shrink-0">{obs.category}</span>
                    </div>

                    <p className="text-xs text-gray-500 mb-3">依据：{obs.evidence}</p>

                    {/* Weight bar */}
                    <div className="flex items-center gap-2 mb-3">
                      <span className="text-xs text-gray-400">权重</span>
                      <div className="flex-1 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                        <div
                          className="h-full bg-gradient-to-r from-indigo-400 to-purple-500 rounded-full transition-all"
                          style={{ width: `${Math.min(obs.weight * 100, 100)}%` }}
                        />
                      </div>
                      <span className="text-xs text-gray-400">{(obs.weight * 100).toFixed(0)}%</span>
                    </div>

                    {/* Feedback buttons */}
                    <div className="flex gap-2">
                      <button
                        disabled={hasFeedback}
                        onClick={() => setObservationFeedback(obs.id, 'positive')}
                        className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                          obs.feedback === 'positive'
                            ? 'bg-green-100 text-green-700'
                            : hasFeedback
                              ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                              : 'bg-gray-100 text-gray-600 hover:bg-green-50 hover:text-green-700'
                        }`}
                      >
                        <ThumbsUp className="w-3.5 h-3.5" />
                        有帮助
                      </button>
                      <button
                        disabled={hasFeedback}
                        onClick={() => setObservationFeedback(obs.id, 'negative')}
                        className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                          obs.feedback === 'negative'
                            ? 'bg-red-100 text-red-700'
                            : hasFeedback
                              ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                              : 'bg-gray-100 text-gray-600 hover:bg-red-50 hover:text-red-700'
                        }`}
                      >
                        <ThumbsDown className="w-3.5 h-3.5" />
                        不准确
                      </button>
                      <button
                        disabled={hasFeedback}
                        onClick={() => setObservationFeedback(obs.id, 'ignore')}
                        className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                          obs.feedback === 'ignore'
                            ? 'bg-gray-200 text-gray-600'
                            : hasFeedback
                              ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                              : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                        }`}
                      >
                        <MinusCircle className="w-3.5 h-3.5" />
                        暂时忽略
                      </button>
                    </div>
                  </div>
                );
              })}
            </>
          )}
        </div>

        {/* Profile Comparison Section */}
        {showComparison && previousSnapshot && (
          <div className="border-t border-gray-200 bg-gradient-to-b from-indigo-50/50 to-white p-5 shrink-0">
            <div className="flex items-center gap-2 mb-4">
              <TrendingUp className="w-5 h-5 text-indigo-600" />
              <h3 className="font-semibold text-gray-700">画像校准结果</h3>
            </div>

            <div className="space-y-3">
              {/* writingTimeFactor */}
              <div className="flex items-center justify-between text-sm">
                <span className="text-gray-600">写作时间系数</span>
                <div className="flex items-center gap-2">
                  <span className="text-gray-400">{previousSnapshot.writingTimeFactor}</span>
                  <ArrowRight className="w-4 h-4 text-indigo-500" />
                  <span className="font-semibold text-indigo-600">{profileSnapshot.writingTimeFactor}</span>
                </div>
              </div>

              {/* recommendedPomodoroMinutes */}
              <div className="flex items-center justify-between text-sm">
                <span className="text-gray-600">推荐番茄时长</span>
                <div className="flex items-center gap-2">
                  <span className="text-gray-400">{previousSnapshot.recommendedPomodoroMinutes} 分钟</span>
                  <ArrowRight className="w-4 h-4 text-indigo-500" />
                  <span className="font-semibold text-indigo-600">{profileSnapshot.recommendedPomodoroMinutes} 分钟</span>
                </div>
              </div>

              {/* startWithLowPressure */}
              <div className="flex items-center justify-between text-sm">
                <span className="text-gray-600">低压优先启动</span>
                <div className="flex items-center gap-2">
                  <span className="text-gray-400">{previousSnapshot.startWithLowPressure ? '是' : '否'}</span>
                  <ArrowRight className="w-4 h-4 text-indigo-500" />
                  <span className="font-semibold text-indigo-600">{profileSnapshot.startWithLowPressure ? '是' : '否'}</span>
                </div>
              </div>
            </div>

            <p className="text-xs text-gray-500 mt-4 mb-3">
              College DDL 已根据你的真实行为校准下一次建议。
            </p>

            <button
              onClick={() => setShowComparison(false)}
              className="w-full py-2.5 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600 text-white text-sm font-medium hover:shadow-lg hover:shadow-indigo-500/25 transition-all"
            >
              知道了
            </button>
          </div>
        )}
      </div>
    </div>
  );
};
